head.script:
scwin.onpageload = function() {
    var data1 = [];
    var data2 = [];
    var data3 = [];
    var row = 10;
    var col = 3;
    for (var i = 0; i < row; i++) {
        for (var j = 0; j < col; j++) {
            if (j === 0) {
                data1.push("label=" + String(i));
                data2.push("L=" + String(i));
                data3.push("_L_:" + String(i));
            } else if (j === 1) {
                data1.push("value=" + String(i));
                data2.push("V=" + String(i));
                data3.push("_V_:" + String(i));
            } else {
                data1.push("dummy=" + String(i));
                data2.push("D=" + String(i));
                data3.push("_d_:" + String(i));
            }
        }
    }
    dataList1.setData(data1);
    dataList2.setData(data2);
    dataList3.setData(data3);
    dataList4.insertRow();
};
scwin.onpageunload = function() {};
scwin.trigger1_onclick = function(e) {
    var obj = {
        "nodeset": "data:dataList2",
        "label": "label",
        "value": "value",
        "width": 1000,
        "height": 800,
        "visibleRowNum": 10,
        "item": [{
            "ref": "label",
            "header": "NLabel"
        }, {
            "ref": "value",
            "header": "NValue"
        }, {
            "ref": "col3",
            "header": "NDummy"
        }]
    };
    selectbox1.setGridItemset(obj);
};
scwin.trigger2_onclick = function(e) {
    var obj = {
        "nodeset": "data:dataList3",
        "label": "label",
        "value": "value",
        "width": 1000,
        "height": 1300,
        "visibleRowNum": 10,
        "item": [{
            "ref": "label",
            "header": "NLabel"
        }, {
            "ref": "value",
            "header": "NValue"
        }, {
            "ref": "col3",
            "header": "NDummy"
        }]
    };
    autoComplete1.setGridItemset(obj);
};
scwin.trigger4_onclick = function(e) {
    var obj1 = {
        "nodeset": "data:dataList2",
        "label": "label",
        "value": "value",
        "width": 600,
        "height": 300,
        "visibleRowNum": 10,
        "item": [{
            "ref": "label",
            "header": "NLabel"
        }, {
            "ref": "value",
            "header": "NValue"
        }, {
            "ref": "col3",
            "header": "NDummy"
        }]
    };
    gridView1.setColumnGridItemset(0, obj1);
};
	scwin.dbClick = function(id) {
		var el = WebSquare.wUnit.getDomById(id);
		scwin.fireDbClick(el);
	}
	scwin.fireDbClick = function(node) {
		if (document.createEventObject) {
			node.fireEvent('ondblclick');
		} else if (document.createEvent) {
			var evt = document.createEvent('MouseEvents');
			evt.initEvent('dblclick', true, false);
			node.dispatchEvent(evt);
		} else if (typeof node.ondblclick == 'function') {
			node.ondblclick();
		}
	}
scwin.checkVal = function() {
	return parseInt(WebSquare.wUnit.getDomById('G_'+$p.id+'gridView1___selectbox_col1_gridViewItemTable_gridView').offsetWidth) > parseInt(parseInt(WebSquare.wUnit.getDomById('gridView1_head_table').style.width))
}	
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 1. 샘플실행 후 '엑셀다운로드'버튼을 클릭한다.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger4').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 2. 셀렉트 박스를 더블클릭한다.
    WebSquare.wUnit.addCommand("set", "scwin.dbClick('gridView1_cell_0_0')");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 3. 셀렉트 박스를 더블클릭한다.
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();
